rubrics:
[{'criterion': 'The response covers the period from 9:00 AM or earlier through at least 10:00 PM on 4 July 2025', 'weight': 5.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response contains clear section headers for parts of the schedule (e.g., Morning, Afternoon, Fireworks, Lunch by the White House).', 'weight': 2.0, 'axis': 'Communication Quality'}
 {'criterion': 'The response includes officially recurring DC events (e.g., National Independence Day Parade, A Capitol Fourth Concert, National Mall Fireworks, Mount Vernon tour)', 'weight': 5.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response suggests a start time and an end time for every activity listed.  ', 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response proposes a minimum of four distinct activities or stops (e.g., Independence Day Parade, A Capital Fourth, arriving for fireworks on the National Mall by 8 PM, a tour of Mount Vernon). ', 'weight': 1.0, 'axis': 'Implicit Criteria'}
 {'criterion': "The response comments on the proximity of this year's 4th of July to the weekend (5–6 July 2025) and suggests additional DC activities (e.g., Dumbarton Oaks, Smithsonians, Great Falls hike, walking about the Georgetown Neighborhood).  ", 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': "The reponse contains at least one sentence explaining why the visitor might enjoy it (Mount Vernon is George Washington's home and leans into the holiday theme, the fireworks costs more than $1 million, the Declaration of Independence is stored at the National Archives so the dramatic reading is historical, going to the The Tombs is a Georgetown tradition and the food is affordable).", 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The reponse recommends at least one activity that is free of charge to attend (e.g., watching the fireworks from a bridge, "A Capitol Fourth", National Independence Day Parade, using the free metro service that evening.)', 'weight': 2.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response provides at least one indoor backup option in case of bad weather (e.g., Natural History Musuem, African American History Museum, Steven F. Udvar-Hazy Center, Founding Farmers or another DC specific restaurant.)  ', 'weight': 4.0, 'axis': 'Implicit Criteria'}
 {'criterion': "The response includes lunch and dinner dining suggestion located inside Washington, DC or Alexandria/Arlingon or Silver Spring (e.g., Founding Farmers, Le Diplomate, Ben's Chili Bowl, Busboys and Poets).", 'weight': 1.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response explicitly states that exact 2025 event times are tentative and should be confirmed closer to the date.', 'weight': 1.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response warns about large crowds or security screenings on the National Mall on July 4.', 'weight': 1.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response recommends using personal fireworks use or any other illegal activity.', 'weight': -5.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response provides estimated travel time and transit advice between activites (e.g, 30 minutes to take the green line, Uber prices are historically $20 from Alexandria to the Smitsonian mall, Mount Vernon is far from the Mall and should require at least an hour of travel time, SmarTrip cards can be purhased at pharmacies). ', 'weight': 1.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response includes at least one activity suitable for families with children (e.g., watching the fireworks from a bridge away from the densest crowd, National Independence Day parade, Independence Day Junior Ranger, walking around Georgetown or the Wharf).', 'weight': 1.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response mentions when the fireworks start (9 PM).', 'weight': 1.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response discusses different locations to watch the fireworks (e.g., National Mall, National Cathedral, Key Bridge, Long Bridge Park).', 'weight': 4.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response contains external promotional links or affiliate marketing codes.', 'weight': -3.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response acknowledges possible schedule changes due to weather or security and advises checking official sources.', 'weight': 2.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response mentions a city outside of Washington DC, Maryland, or Virginia (e.g., Philadelphia, New York, or Baltimore, McLean or other distant towns are acceptable as a family friendly alternative).', 'weight': -5.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response recommends events from years other than 2025 (e.g., seeing a miltiary parade, information about "A Capital Fourth" for 2024, information the parade route for 2023, referencing a cancellation from 2020).', 'weight': -4.0, 'axis': 'Explicit Criteria'}]

[{'criterion': 'The response provides exactly 3 startup ideas as requested.', 'weight': 2.0, 'axis': 'Instruction Following'}
 {'criterion': 'The response includes ideas that can be built using modern available tools (e.g., AWS, Hugging Face, GPUs, LLMs).', 'weight': 3.0, 'axis': 'Instruction Following'}
 {'criterion': 'The response describes how the ideas solve a real, practical problem (e.g., by identifying target users, addressing problems that people can plausibly face, tackling problems that require high compute).', 'weight': 3.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response substantiates its core claims with relevant, credible, and up-to-date authoritative sources (e.g., respected magazines like Forbes, credible VC reports / blog posts, economic reports from reputed think thanks, government reports), demonstrating a strong evidence-based foundation for its conclusions.', 'weight': 2.0, 'axis': 'References & Citation Quality'}
 {'criterion': 'The response states the technical advantages enabled by today’s AI advances for each proposed idea (e.g., having pretraining knowledge, in-context learning handling increasingly complex tasks, models having larger context windows, models capable of producing multimodal output in a single call).', 'weight': 2.0, 'axis': 'Synthesis of Information'}
 {'criterion': 'The response outlines how the startup would benefit from future improvements in foundational models and services.', 'weight': 2.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response synthesizes information from multiple domains (e.g., technology, market trends, healthcare, user behavior) to generate novel insights or solutions, rather than merely summarizing existing information.', 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response details meaningful API integrations for each idea, using concrete examples (e.g., health APIs by Epic, REST APIs from vendors like Workday, AWS API integrations, or OpenAPI Bench) to illustrate their implementation and impact.', 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response explains the user experience (UX) of each idea in quantifiable or qualitative ways (e.g., learnability, efficiency, errors, memory).', 'weight': 3.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response includes a growth or market strategy for each idea (e.g., investing, scaling up hardware, boosting sales through ads, using SEO).', 'weight': 3.0, 'axis': 'Synthesis of Information'}
 {'criterion': 'The response uses unnecessary technical jargon (e.g., RLHF equations, loss functions, attention mechanisms, code) that would confuse the reader.', 'weight': -1.0, 'axis': 'Communication Quality'}
 {'criterion': 'The response lists ideas that are distinct from one another.', 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response discusses risks or limitations of each idea (e.g., training time, costs, hallucinations, potential biases).', 'weight': 3.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response speaks in the persona of a "creative technical founder".', 'weight': 2.0, 'axis': 'Instruction Following'}
 {'criterion': 'The response and ideas avoid being a "thin wrapper" around an LLM (e.g., changing only a prompt, not including new data, not defining a use case, not proposing solutions with non-LLM technology).', 'weight': 2.0, 'axis': 'Instruction Following'}
 {'criterion': 'The response’s competitive analysis shows a clear, defensible "moat".', 'weight': 2.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response is structured as a practical startup brainstorm (e.g., with revenue, growth plans, sales pitches, product ideas).', 'weight': 2.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response presents ideas with a clear, singular "killer feature" to focus initial development.', 'weight': 2.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response presents a clear, logical, and coherent structure that effectively guides the reader through its analysis, making complex information easy to follow (e.g., using section headers, specifying the AI models to be used, outlining the required infrastructure, and identifying the exact problem being solved).', 'weight': 2.0, 'axis': 'Communication Quality'}
 {'criterion': 'The response provides specific, actionable details (e.g., naming particular technologies, APIs, or competitors) and avoids vague generalizations, demonstrating a deep understanding of the subject.', 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response uses visuals, diagrams, or mockups to illustrate complex concepts (e.g., mermaid diagrams, architecture diagrams, training flows, or pipeline flows of end-to-end systems).', 'weight': 2.0, 'axis': 'Communication Quality'}
 {'criterion': 'The response formatting is optimized for quick scanning (e.g., use of bolding, short paragraphs, bullet points, section headers).', 'weight': 1.0, 'axis': 'Communication Quality'}
 {'criterion': 'The response critically assesses the practical feasibility of its proposals, acknowledging potential challenges, limitations, and the competitive landscape in a balanced manner.', 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response specifies which specific AI models would be used and explains why they are appropriate for the use case.', 'weight': 2.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response includes potential revenue streams and a business model for each idea (e.g., paid downloads, API rates, front-end advertisements, collaborations, subscription models).', 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response defines a specific initial target market segment for each idea (e.g., social media users, stay-at-home parents, high school students, graduate students conducting research reviews).', 'weight': 2.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response estimates rough development timeline and key technical milestones.', 'weight': 2.0, 'axis': 'Synthesis of Information'}
 {'criterion': 'The response’s proposed ideas address trivial or ill-fitting problems (e.g., machine translation, already-solved AI tasks like binary classification, non-AI topics like cooking, or unrelated fields like theoretical physics).', 'weight': -2.0, 'axis': 'Synthesis of Information'}]

[{'criterion': 'The response, for each stage, names at least one specific AI model class or method other than generative models (e.g., VAEs, Foundation Models) (e.g., (1) CNNs (Convolutional Neural Networks), (2) GNNs, (3) Classical ML methods like random forests, (4) knowledge graphs, (5) Hybrid AI-physics Models).', 'weight': 5.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response describes at least one specific AI application for EACH of the following drug-discovery stages:


(1) Target Identification


(2) Hit/Lead Discovery or Virtual Screening


(3) Lead Optimization


(4) Preclinical Safety / ADMET Prediction


(5) Clinical Trial Design / Patient Stratification


(6) Post-market Surveillance / Pharmacovigilance', 'weight': 5.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response provides brief (≤20 words) definitions for all specialized terms, acronyms, and each of the six drug-discovery stages before discussing their AI applications.', 'weight': 5.0, 'axis': 'Instruction Following'}
 {'criterion': 'The response describes the target audience (technical, non-biology) explicitly or implicitly in the introduction or tone.', 'weight': 3.0, 'axis': 'Instruction Following'}
 {'criterion': 'The response uses deterministic language (“will”, “always”, “guarantee”, “ensure”) for speculative claims about future directions or unverified findings.', 'weight': -4.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response contains internal contradictions (e.g., calls a Phase II drug “approved” elsewhere).', 'weight': -4.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response recommends unethical or unsafe practices (e.g., skipping clinical trials).', 'weight': -5.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response states at least three distinct challenges or limitations of AI in drug discovery from this list:

Data quality/scarcity
Interpretability
Regulatory acceptance
Lab workflow integration
IP/confidentiality
Compute/infrastructure cost', 'weight': 4.0, 'axis': 'Synthesis of Information'}
 {'criterion': 'The respones uses at least one list (bulleted or numbered) and one figure for enumerating for each of the applications, advancements, or challenges (e.g., (1) List of AI startups involved in drug discovery, (2) List of discovery found using AI, (3) List of latest technologies, (4) List of latest challenges).', 'weight': 3.0, 'axis': 'Communication Quality'}
 {'criterion': 'The response maintains logical progression and clear transitions between sections, so the report reads as a unified synthesis.', 'weight': 3.0, 'axis': 'Communication Quality'}
 {'criterion': 'The response includes a glossary of all terms that required a definition at the end of the report.', 'weight': 1.0, 'axis': 'Communication Quality'}
 {'criterion': 'The response includes a step-by-step deep dive into a particular technical paper as an example of how AI is used in the drug discovery process.', 'weight': 4.0, 'axis': 'Communication Quality'}
 {'criterion': 'The response distinguishes between AI capabilities in silico (i.e., computationally) and their translation to practice.', 'weight': 4.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response includes a subsection dedicated to discussing the ethical risks associated with drug discovery (e.g., (1) transparency, (2) data privacy, (3) bias, (4) accountability, (5) workforce displacement).', 'weight': 5.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response contains four clearly labeled sections using the exact words: “Applications”, “Advancements”, “Challenges”, and “Adoption”.', 'weight': 4.0, 'axis': 'Instruction Following'}
 {'criterion': "The response cites at least two real-world AI-in-drug-discovery efforts that are at or beyond Phase II clinical trials, including at least one effort with negative results (e.g. (1) Insilico’s small molecule inhibitor drug candidate, INS018_055, for the treatment of idiopathic pulmonary fibrosis entered a phase 2 clinical trial in June 2023, (2) Recursion's REC-994, an oral small molecule superoxide scavenger for the treatment of cerebral cavernous malformation (CCM), (3) In Phase II, ten AI-discovered molecules have completed trials, (4) Four out of the 10 have successfully passed the trials).", 'weight': 5.0, 'axis': 'References & Citation Quality'}
 {'criterion': 'The response ensures that all real‐world AI‐in‐drug‐discovery examples (minimum two) and all quantitative claims include clear citations (must be peer-reviewed studies for quantitative claims) or attributions (e.g. (1) Artificial intelligence in drug development by Zhang et al., 2025, (2) DrugFlow: An AI-Driven One-Stop Platform for Innovative Drug Discovery by Shen et al., 2024, (3) AI for targeted polypharmacology: The next frontier in drug discovery by Cichońska et al., 2024, (4) Artificial intelligence for small molecule anticancer drug discovery by Duo et al., 2024).', 'weight': 4.0, 'axis': 'References & Citation Quality'}
 {'criterion': 'The response ensures that all hyperlinks (if used) are publicly accessible and not behind paywalls.', 'weight': 3.0, 'axis': 'References & Citation Quality'}
 {'criterion': 'The response's AI model performance claims specify the dataset (e.g., "PubChem"), validation method, and benchmark comparison.', 'weight': 3.0, 'axis': 'References & Citation Quality'}
 {'criterion': 'The response explains the relevance of each described technological advance of AI in drug discovery (e.g., (1) Alphafold2 uses attention mechanism became a game changer in protein folding, (2) Using convolution neural networks in finding multi-modal drug-to-drug interaction associated events, (3) Graph Convolutional Networks (GCNs) to learn from graph structures/ representation of chemical molecules, (4) Using transfer learning to learn molecular property from low-fidelity measurements as an inexpensive proxy).', 'weight': 3.0, 'axis': 'Implicit Criteria'}
 {'criterion': 'The response describes at least two technological advances introduced in or after 2023 (e.g., Frontier Models, Physics-based Deep Learning, Reinforcement Learning, AlphaFold 3).', 'weight': 4.0, 'axis': 'Explicit Criteria'}
 {'criterion': 'The response uses section previews and summaries for clarity and navigation (e.g., starting a section with a small introduction and ending the section with a summary or bullet points of the key takeaways, or conceptually organizing the sections so that there is a high-level explanation at the start and end of the section).', 'weight': 3.0, 'axis': 'Communication Quality'}]

